#include <bits/stdc++.h>
using namespace std;

struct Edge {
  int from, to;
  double capacity;
  Edge(int s, int d, double cap): from(s), to(d), capacity(cap) {}
};

struct Vertex {
  vector<int> incident_edges;
};

struct Network {
  vector<Vertex> vertices;
  vector<Edge> edges;

  Network(int V, int E_capacity) {
    vertices.resize(V);
    edges.reserve(E_capacity);
  }

  void link(int u, int v, double cap) {
    edges.emplace_back(u, v, cap);
    vertices[u].incident_edges.push_back(int(edges.size()) - 1);
  }

  vector<int> find_path(int src, int dst, const vector<double>& flow, double* bottleneck) {
    using State = pair<double, int>;
    set<State, greater<State>> pq;
    vector<double> best_cap(vertices.size(), 0.0);
    vector<int> prev_edge(vertices.size(), -1);

    best_cap[src] = numeric_limits<double>::infinity();
    pq.emplace(best_cap[src], src);

    while (!pq.empty() && best_cap[dst] == 0) {
      auto [cap, node] = *pq.begin();
      pq.erase(pq.begin());

      for (int eid : vertices[node].incident_edges) {
        const Edge& e = edges[eid];
        double residual = e.capacity - flow[eid];
        if (residual > 0) {
          double new_cap = min(cap, residual);
          if (new_cap > best_cap[e.to]) {
            pq.erase({best_cap[e.to], e.to});
            best_cap[e.to] = new_cap;
            pq.emplace(best_cap[e.to], e.to);
            prev_edge[e.to] = eid;
          }
        }
      }
    }

    *bottleneck = best_cap[dst];
    vector<int> path;
    for (int e = prev_edge[dst]; e != -1; e = prev_edge[edges[e].from])
      path.push_back(e);
    return path;
  }

  double flow(int source, int sink) {
    Network res(vertices.size(), edges.size() * 2);
    vector<double> f(edges.size() * 2, 0.0);

    for (size_t i = 0; i < edges.size(); ++i) {
      res.link(edges[i].from, edges[i].to, edges[i].capacity);
      res.link(edges[i].to, edges[i].from, 0.0);
    }

    double total = 0.0;
    double cap;
    for (auto path = res.find_path(source, sink, f, &cap); !path.empty() && cap > 0;
         path = res.find_path(source, sink, f, &cap)) {
      for (int e : path) {
        int rev = (e % 2 == 1) ? e - 1 : e + 1;
        f[e] += cap;
        f[rev] -= cap;
      }
      total += cap;
    }

    for (int eid : res.vertices[source].incident_edges)
      total += f[eid];
    return total;
  }
};

int n, T;
struct Cell {
  int x, y;
  array<bool, 61> affected{};
  array<bool, 61> passable{};
  int scientists{}, capsules{};

  Cell() { passable.fill(true); }

  int node_index(int t) const { return 2 + x + n*y + n*n*t; }

  void quarantine() { passable.fill(false); }

  void infect(int t = 0) {
    if (passable[t]) {
      passable[t] = false;
      affected[t] = true;
    }
  }

  void propagate(int t);
};

Cell grid[10][10];

void Cell::propagate(int t) {
  if (affected[t]) {
    infect(t + 1);
    if (x > 0) grid[x - 1][y].infect(t + 1);
    if (x < n - 1) grid[x + 1][y].infect(t + 1);
    if (y > 0) grid[x][y - 1].infect(t + 1);
    if (y < n - 1) grid[x][y + 1].infect(t + 1);
  }
}

string node_label(int id) {
  if (id == 0) return "source";
  if (id == 1) return "sink";
  stringstream ss;
  int row = (id - 2) % n;
  int col = ((id - 2 - row) % (n*n)) / n;
  int tm = (id - 2 - row - col*n) / (n*n);
  ss << "(" << row << "," << col << "," << tm << ")";
  return ss.str();
}

int main() {
  ios::sync_with_stdio(false);
  cin >> n >> T;

  for (int i = 0; i < n; ++i) {
    string row;
    cin >> row;
    for (int j = 0; j < n; ++j) {
      grid[i][j].x = i;
      grid[i][j].y = j;
      if (row[j] == 'Y') grid[i][j].quarantine();
      else if (row[j] == 'Z') grid[i][j].infect();
      else grid[i][j].scientists = row[j] - '0';
    }
  }

  for (int i = 0; i < n; ++i) {
    string row;
    cin >> row;
    for (int j = 0; j < n; ++j) {
      if (row[j] != 'Y' && row[j] != 'Z')
        grid[i][j].capsules = row[j] - '0';
    }
  }

  for (int step = 0; step <= T; ++step)
    for (int i = 0; i < n; ++i)
      for (int j = 0; j < n; ++j)
        if (step < T) grid[i][j].propagate(step);

  Network net(n*n*(T+1)+2, 100*4*60);
  for (int i = 0; i < n; ++i)
    for (int j = 0; j < n; ++j) {
      const Cell& cell = grid[i][j];
      if (cell.scientists) net.link(0, cell.node_index(0), cell.scientists);
      if (cell.capsules) net.link(cell.node_index(T), 1, cell.capsules);
      for (int t = 0; t < T; ++t) {
        if (cell.capsules) net.link(cell.node_index(t), cell.node_index(T), 1000);
        if (cell.passable[t]) {
          if (i > 0 && grid[i-1][j].passable[t])
            net.link(cell.node_index(t), grid[i-1][j].node_index(t+1), 1000);
          if (i < n-1 && grid[i+1][j].passable[t])
            net.link(cell.node_index(t), grid[i+1][j].node_index(t+1), 1000);
          if (j > 0 && grid[i][j-1].passable[t])
            net.link(cell.node_index(t), grid[i][j-1].node_index(t+1), 1000);
          if (j < n-1 && grid[i][j+1].passable[t])
            net.link(cell.node_index(t), grid[i][j+1].node_index(t+1), 1000);
        }
      }
    }

  cout << int(net.flow(0, 1)) << '\n';
  return 0;
}
